"""Startup and live memory requests generated by Lean, checked against DOS output.
No DOS trace, memory sample, or expected color is supplied to the live process.
"""
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest

ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'scripts'))
from live_compare import PacketReader


def sha(data):return hashlib.sha256(data).hexdigest()


class DosHeapTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.wad=ROOT/'artifacts/doom-shareware-1.9/doom1.wad'
        if not cls.wad.exists():raise unittest.SkipTest('shareware WAD not installed')
        cls.spec=json.loads((ROOT/'tests/reference/dos-heap-commands.json').read_text())
        if sha(cls.wad.read_bytes())!=cls.spec['wad_sha256']:
            raise AssertionError('DOS heap tests require the pinned shareware WAD')

    def test_independent_startup_matches_original_allocations_and_frees(self):
        result=subprocess.run([str(ROOT/'.lake/build/bin/dos-startup-probe'),str(self.wad)],
                              capture_output=True,check=True,text=True)
        self.assertEqual(result.stderr,'')
        rows=result.stdout.splitlines()
        self.assertEqual(len(rows),self.spec['startup_operations'])
        self.assertEqual(sum(r.startswith('alloc ') for r in rows),self.spec['startup_allocations'])
        self.assertEqual(sha(''.join('0 '+r+'\n' for r in rows).encode()),self.spec['startup_sha256'])

    def test_live_gameplay_generates_dos_requests_and_all_overread_frames(self):
        commands=[row[1:] for row in self.spec['runs'] for _ in range(row[0])]
        encoded=''.join(' '.join(map(str,c))+'\n' for c in commands).encode()
        self.assertEqual(sha(encoded),self.spec['commands_sha256'])
        with tempfile.TemporaryDirectory() as folder:
            path=Path(folder);trace=path/'heap.txt'
            with (path/'stderr').open('wb') as error:
                p=subprocess.Popen([str(ROOT/'.lake/build/bin/live-render-probe'),str(self.wad),'--dos-presentation'],
                    stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=error,
                    env={**os.environ,'LEANDOOM_HEAP_TRACE':str(trace)})
                reader=PacketReader(p.stdout.fileno())
                try:
                    for tic,cmd in enumerate(commands,1):
                        p.stdin.write((' '.join(map(str,cmd))+'\n').encode());p.stdin.flush()
                        _,frame=reader.packet(timeout=60)
                        if str(tic) in self.spec['frames']:
                            self.assertEqual(sha(frame),self.spec['frames'][str(tic)],f'frame {tic}')
                    p.stdin.close()
                    self.assertEqual(p.wait(timeout=10),0)
                finally:
                    if p.poll() is None:p.terminate();p.wait(timeout=10)
                    p.stdout.close()
                    if not p.stdin.closed:p.stdin.close()
            self.assertEqual((path/'stderr').read_text(),'')
            rows=trace.read_bytes()
            self.assertEqual(len(rows.splitlines()),self.spec['operations'])
            self.assertEqual(sha(rows),self.spec['operations_sha256'])


if __name__=='__main__':unittest.main()
